import{_t as e,it as t,n,rt as r}from"./chunks/framework.uM88Qy9F.js";var i=JSON.parse(`{"title":"数据模型","description":"","frontmatter":{},"headers":[],"relativePath":"backend/data-model.md","filePath":"backend/data-model.md","lastUpdated":1794049926000}`),a={name:`backend/data-model.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="数据模型" tabindex="-1">数据模型 <a class="header-anchor" href="#数据模型" aria-label="Permalink to “数据模型”">​</a></h1><p>本页说明各包实体落在平台库还是租户库、各自实现哪些协议接口，以及索引与唯一性规则，适用于需要了解表结构归属的后端开发者。实体基类见<a href="./entity">实体基类</a>。</p><h2 id="落点规则" tabindex="-1">落点规则 <a class="header-anchor" href="#落点规则" aria-label="Permalink to “落点规则”">​</a></h2><p>数据模型按「库决定协议」划分：实体落在哪个库，决定它用哪组基类、实现哪些接口。</p><table tabindex="0"><thead><tr><th></th><th>平台库实体</th><th>租户库实体</th></tr></thead><tbody><tr><td>基类</td><td><code>AppEntity</code> / <code>AppRecord</code> / <code>AppAuditedEntity</code> / <code>AppAggregateRoot</code></td><td><code>TenantScopedEntity</code> / <code>TenantScopedRecord</code> / <code>TenantScopedAuditedEntity</code> / <code>TenantScopedAggregateRoot</code></td></tr><tr><td><code>IMultiTenant</code></td><td>不实现</td><td>实现，框架仓储按当前租户严格过滤</td></tr><tr><td>归属</td><td>需要分侧时实现 <code>IOwnedByTenant</code>，列 <code>OwnerTenantId</code>（平台为 <code>platform</code>）；账号用 <code>HomeTenantId</code></td><td><code>TenantId</code>；平台一侧的数据以 <code>platform</code> 为租户落在同一张表</td></tr><tr><td>连接</td><td>永远是默认连接（平台库），独立库的租户也读写平台库里的这些表</td><td>租户有独立库时落 <code>shard</code> 连接，否则与平台库同库、按 <code>tenant_id</code> 过滤</td></tr><tr><td>例子</td><td>用户、会话、租户、角色与授权、菜单、参数、字典、模板、各类配置</td><td>部门、岗位、文件、通知与收件箱、日志、聊天、知识文档</td></tr></tbody></table><p>框架仓储要求租户库实体的调用带租户，平台一侧（<code>platform</code>）的行经 Runtime 的 <code>SideRows</code> 按侧读写。平台扫各租户库的后台工作（日志写入、保留清理、独立库初始化与升级）在自建作用域里经框架 <code>TenantShardScope</code> 按租户绑定分片，不在同一个上下文里切换租户。</p><h2 id="平台库实体" tabindex="-1">平台库实体 <a class="header-anchor" href="#平台库实体" aria-label="Permalink to “平台库实体”">​</a></h2><h3 id="身份-identity" tabindex="-1">身份（Identity） <a class="header-anchor" href="#身份-identity" aria-label="Permalink to “身份（Identity）”">​</a></h3><table tabindex="0"><thead><tr><th>实体</th><th>说明</th></tr></thead><tbody><tr><td><code>SysUser</code></td><td>账号：<code>HomeTenantId</code> 为注册地租户（平台账号为 <code>platform</code>），状态、是否系统内置账号、资料与头像</td></tr><tr><td><code>SysUserSecurity</code></td><td>账号安全：密码散列、失败计数、锁定期、双因素（密钥加密存储）、开放接口签名设置、登录策略</td></tr><tr><td><code>SysUserSession</code></td><td>会话：ID 即令牌的 <code>sid</code>，<code>ActiveTenantId</code> 为会话当前所在的租户（平台为空）；刷新令牌散列、客户端信息、登录地点、锁屏、模仿发起人</td></tr><tr><td><code>SysPasswordHistory</code></td><td>密码历史（不可复用的深度见 <code>BasicApp:Auth:PasswordHistoryDepth</code>）</td></tr><tr><td><code>SysUserSetting</code></td><td>用户设置（用户 × 场景 × 键，值是 JSON）：偏好、收藏、工作台布局</td></tr><tr><td><code>SysUserNotificationPreference</code></td><td>通知偏好</td></tr><tr><td><code>SysUserExternalLogin</code></td><td>第三方账号绑定</td></tr><tr><td><code>SysUserApiCredential</code></td><td>开放接口凭证（密钥加密存储）</td></tr></tbody></table><h3 id="租户-tenancy" tabindex="-1">租户（Tenancy） <a class="header-anchor" href="#租户-tenancy" aria-label="Permalink to “租户（Tenancy）”">​</a></h3><table tabindex="0"><thead><tr><th>实体</th><th>说明</th></tr></thead><tbody><tr><td><code>SysTenant</code></td><td>租户：目录键 <code>TenantId</code>、名称、状态、到期、管理员（即所有者）、套餐、配额、隔离方式与独立库状态；与框架 <code>TenantRecord</code> 同事务同步</td></tr><tr><td><code>SysTenantMember</code></td><td>租户成员与运维支持成员，带生效与到期</td></tr><tr><td><code>SysEdition</code> / <code>SysEditionGrant</code></td><td>套餐（价格、计费周期、用户与存储配额）与权限白名单</td></tr></tbody></table><h3 id="授权-access" tabindex="-1">授权（Access） <a class="header-anchor" href="#授权-access" aria-label="Permalink to “授权（Access）”">​</a></h3><p>除 <code>SysMenu</code> 外都实现 <code>IOwnedByTenant</code>，按侧分开。</p><table tabindex="0"><thead><tr><th>实体</th><th>说明</th></tr></thead><tbody><tr><td><code>SysRole</code></td><td>角色，带数据范围</td></tr><tr><td><code>SysUserRole</code></td><td>角色指派，带生效与到期</td></tr><tr><td><code>SysRoleInheritance</code></td><td>角色继承（只存直接边）</td></tr><tr><td><code>SysPermissionRule</code></td><td>Deny 与带有效期或原因的授予；普通授予只写框架的 <code>PermissionGrantRecord</code></td></tr><tr><td><code>SysPermissionDelegation</code></td><td>限时委托</td></tr><tr><td><code>SysPermissionCondition</code></td><td>挂在授权绑定上的 ABAC 条件</td></tr><tr><td><code>SysRoleDataScope</code> · <code>SysUserDataScope</code> · <code>SysUserDataScopeDepartment</code></td><td>角色的自定义部门、用户级数据范围覆盖及其部门</td></tr><tr><td><code>SysFieldSecurityRule</code></td><td>字段安全规则</td></tr><tr><td><code>SysAccessPolicy</code> · <code>SysAccessPolicyCondition</code></td><td>访问策略及其条件</td></tr><tr><td><code>SysConstraintRule</code> · <code>SysConstraintRuleItem</code></td><td>约束规则及其规则项</td></tr><tr><td><code>SysSessionRole</code></td><td>会话激活的角色</td></tr><tr><td><code>SysMenu</code></td><td>菜单：两侧共用一棵树，页面节点由页面登记派生，另有运营建的目录与外链</td></tr></tbody></table><h3 id="平台能力与可选模块" tabindex="-1">平台能力与可选模块 <a class="header-anchor" href="#平台能力与可选模块" aria-label="Permalink to “平台能力与可选模块”">​</a></h3><table tabindex="0"><thead><tr><th>包</th><th>实体</th></tr></thead><tbody><tr><td>Settings</td><td><code>SysConfig</code>、<code>SysDict</code>、<code>SysDictItem</code>、<code>SysNumberingRule</code>、<code>SysNumberingAllocation</code>（均 <code>IOwnedByTenant</code>）</td></tr><tr><td>Notification</td><td><code>SysMessageTemplate</code>、<code>SysEmail</code>、<code>SysSms</code>、<code>SysBotMessage</code>、<code>SysEmailConfig</code>、<code>SysSmsConfig</code>、<code>SysBotConfig</code>（均 <code>IOwnedByTenant</code>）；<code>SysTelegramBot</code>、<code>SysTelegramMessage</code>（只在平台）</td></tr><tr><td>Files</td><td><code>SysStorageConfig</code>（<code>IOwnedByTenant</code>，密钥加密存储）</td></tr><tr><td>OpenPlatform</td><td><code>SysOAuthApp</code>、<code>SysOAuthCode</code>、<code>SysOAuthToken</code>、<code>SysOAuthConsent</code>、<code>SysOAuthSigningKey</code></td></tr><tr><td>Printing</td><td><code>SysPrintTemplate</code>（<code>IOwnedByTenant</code>）</td></tr><tr><td>AI</td><td><code>SysAiProvider</code>、<code>SysAiPrompt</code>、<code>SysAiAssistant</code>（只在平台）</td></tr><tr><td>CodeGeneration</td><td><code>SysCodeGenDataSource</code>、<code>SysCodeGenTable</code>、<code>SysCodeGenTableColumn</code>、<code>SysCodeGenTemplate</code>、<code>SysCodeGenHistory</code>（只在平台）</td></tr><tr><td>Runtime</td><td><code>SysVersion</code>、<code>SysMigrationHistory</code>：结构版本台账与升级脚本记录，平台库与每个独立库各一份</td></tr></tbody></table><h2 id="租户库实体" tabindex="-1">租户库实体 <a class="header-anchor" href="#租户库实体" aria-label="Permalink to “租户库实体”">​</a></h2><table tabindex="0"><thead><tr><th>包</th><th>实体</th><th>说明</th></tr></thead><tbody><tr><td>Organization</td><td><code>SysDepartment</code>、<code>SysDepartmentHierarchy</code>、<code>SysPosition</code>、<code>SysUserDepartment</code></td><td>部门（闭包表维护层级）、岗位、部门成员（聚合根，发出领域事件）</td></tr><tr><td>Identity</td><td><code>SysUserStatistics</code></td><td>用户使用统计，在注册地租户</td></tr><tr><td>Access</td><td><code>SysPermissionRequest</code></td><td>授权申请</td></tr><tr><td>Files</td><td><code>SysFile</code>、<code>SysFileStorage</code>、<code>SysFileUpload</code>、<code>SysExportTask</code>、<code>SysImportHistory</code></td><td>文件、副本、分片上传会话、导出任务、导入历史</td></tr><tr><td>Notification</td><td><code>SysNotification</code>、<code>SysUserNotification</code></td><td>通知与按人投递</td></tr><tr><td>Auditing</td><td><code>SysAccessLog</code>、<code>SysLoginLog</code>、<code>SysExceptionLog</code>、<code>SysDiffLog</code>、<code>SysPermissionChangeLog</code>、<code>SysConditionHit</code>、<code>SysOpenApiLog</code></td><td>七类日志，按月分表（<code>[SplitTable(SplitType.Month)]</code>），只追加</td></tr><tr><td>Workflow</td><td><code>SysWorkflowTaskRecord</code>、<code>SysWorkflowMessageReceipt</code></td><td>审批记录（办理、转办、加签、抄送）与已处理的工作流事件回执</td></tr><tr><td>Chat</td><td><code>SysChatConversation</code>、<code>SysChatConversationMember</code>、<code>SysChatMessage</code>、<code>SysChatMessageReaction</code></td><td>会话、成员、消息、表情回应</td></tr><tr><td>AI</td><td><code>SysKnowledgeDocument</code></td><td>知识文档</td></tr></tbody></table><p>操作日志没有应用表：它就是框架的操作审计 <code>audit_record</code>（经 <code>Auditing.Database</code> 落库），Auditing 包只提供查询面。</p><p>按月分表的日志不在基线脚本里，写入时由框架按月建表。</p><h2 id="框架-provider-的表" tabindex="-1">框架 Provider 的表 <a class="header-anchor" href="#框架-provider-的表" aria-label="Permalink to “框架 Provider 的表”">​</a></h2><p>基线 <code>Schema/6.0.0/0001-baseline.sql</code> 同时包含框架 Provider 的表，由同一套升级器管理：</p><table tabindex="0"><thead><tr><th>表</th><th>来源</th></tr></thead><tbody><tr><td><code>tenant_record</code></td><td><code>MultiTenancy.Database</code>：租户目录与分片属性</td></tr><tr><td><code>permission_grant_record</code></td><td><code>Security.Database</code>：权限授予</td></tr><tr><td><code>audit_record</code></td><td><code>Auditing.Database</code>：操作审计（即操作日志）</td></tr><tr><td><code>job_entity</code>、<code>trigger_entity</code>、<code>job_run_entity</code>、<code>scheduler_lease_entity</code>、<code>scheduler_node_entity</code></td><td><code>Scheduling.Database</code>：作业、触发器、运行记录、租约与节点</td></tr><tr><td><code>workflow_*_record</code>、<code>platform_workflow_*_record</code>、<code>workflow_lock_record</code></td><td><code>Workflow.Database</code>：流程定义、实例、节点实例与书签（租户与平台各一组）及租约</td></tr><tr><td><code>message_translation</code></td><td><code>Localization.Database</code>：运营覆盖的译文</td></tr><tr><td><code>outbox_message</code></td><td>事务发件箱</td></tr></tbody></table><h2 id="索引与唯一性" tabindex="-1">索引与唯一性 <a class="header-anchor" href="#索引与唯一性" aria-label="Permalink to “索引与唯一性”">​</a></h2><p>编码、键名这类唯一性由操作在写入前检查并返回本包的 <code>CONFLICT</code> 错误码（如参数键在本侧唯一），数据库再用唯一索引兜住并发写入：</p><ul><li>软删除实体用部分唯一索引，只约束未删除的行（<code>ux_&lt;表&gt;_&lt;列&gt;… WHERE is_deleted = false</code>）：同一个编码删了再建、再删都不冲突。实体上写 <code>[ActiveUniqueIndex(nameof(…))]</code>，开发库由 Runtime 在建表之后补建，独立库在初始化时补建，生产库随基线脚本建出；只支持 PostgreSQL 与 SQLite。</li><li>不软删除的实体（关联表、只增的记录）用唯一的 <code>[SugarIndex]</code>；外键查找与列表的筛选、排序用普通 <code>[SugarIndex]</code>（<code>ix_&lt;表&gt;_&lt;列&gt;</code>）。按月分表的日志用 <code>{split_table}</code> 占位，每张月表各带一份。</li><li>结构测试（<code>EntityIndexTests</code>）守护：软删除实体不写唯一的 <code>[SugarIndex]</code>，部分唯一索引只用于软删除实体，列都是实体的属性，索引名不超过 PostgreSQL 的 63 字符（过长时写 <code>Name</code> 给一个短名）且不重名。</li></ul><p>跨归属的规则（如字典码平台与租户不可重复）索引表达不了，只靠操作里的检查。并发写入撞上唯一 <code>[SugarIndex]</code> 时，框架仓储核对后按唯一键重复返回 <code>PERSISTENCE_CONFLICT_003</code>；撞上 <code>[ActiveUniqueIndex]</code> 建的部分唯一索引时框架识别不了，第二个写入方拿到的是数据库错误。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./database">数据库配置</a> · <a href="./multi-tenancy">多租户 SaaS</a> · <a href="./upgrade">表结构升级</a></li></ul>`,29)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};